from collections import deque, defaultdict

def comps(grid, rmax=13):
    H=len(grid); W=len(grid[0]); seen=set(); out=[]
    # infer background from most common value in top 14 rows
    from collections import Counter
    bg=Counter(x for row in grid[:rmax] for x in row).most_common(1)[0][0]
    for r in range(rmax):
      for c in range(W):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          y,x=q.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<rmax and 0<=xx<W and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx)); q.append((yy,xx))
        out.append((col,cells,(min(y for y,x in cells),min(x for y,x in cells),max(y for y,x in cells),max(x for y,x in cells))))
    return bg,out
